package config

import (
	"fmt"
	"reflect"

	"gopkg.in/yaml.v3"
)

// PrepareGroupingConfigDocument preserves the supplied YAML tree and fills only
// source grouping IDs generated by the transaction owner. It rejects mismatched
// source sequences, existing identities, and any changed credential material.
// The returned document contains secrets and must not be logged.
func PrepareGroupingConfigDocument(data []byte, cfg *Config) ([]byte, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil || len(doc.Content) != 1 {
		return nil, fmt.Errorf("grouping: invalid configuration document")
	}
	root := expandConfigAliases(doc.Content[0])
	if cfg == nil || root.Kind != yaml.MappingNode {
		return nil, fmt.Errorf("grouping: invalid configuration snapshot")
	}
	var source Config
	if err := root.Decode(&source); err != nil {
		return nil, fmt.Errorf("grouping: invalid credential document")
	}
	if err := fillGroupingDocumentIDs(root, &source, cfg); err != nil {
		return nil, err
	}
	if !sameGroupingDocumentCredentials(&source, cfg) {
		return nil, fmt.Errorf("grouping: credential source sequence changed")
	}
	doc.Content[0] = root
	return yaml.Marshal(&doc)
}

func fillGroupingDocumentIDs(root *yaml.Node, source, cfg *Config) error {
	oldRefs, err := groupingCredentialIDRefs(source)
	if err != nil {
		return err
	}
	newRefs, err := groupingCredentialIDRefs(cfg)
	if err != nil {
		return err
	}
	if err = validateGroupingIDRefs(newRefs, false); err != nil {
		return err
	}
	nodes, err := groupingDocumentCredentialNodes(root)
	if err != nil || len(nodes) != len(oldRefs) {
		return fmt.Errorf("grouping: credential source sequence changed")
	}
	indices, err := groupingDocumentSourceIndices(source, oldRefs, newRefs)
	if err != nil {
		return err
	}
	for i, index := range indices {
		old, next := oldRefs[index], newRefs[i]
		if *old.id != "" && *old.id != *next.id {
			return fmt.Errorf("grouping: credential identity changed")
		}
		*old.id = *next.id
		if *next.id != "" {
			setYAMLPath(nodes[index], "grouping-id", &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: *next.id})
		}
	}
	return nil
}

func groupingDocumentSourceIndices(source *Config, oldRefs, newRefs []groupingIDRef) ([]int, error) {
	if len(oldRefs) == len(newRefs) {
		indices := make([]int, len(newRefs))
		for i := range newRefs {
			if oldRefs[i].path != newRefs[i].path {
				return nil, fmt.Errorf("grouping: credential source sequence changed")
			}
			indices[i] = i
		}
		return indices, nil
	}
	// Track source positions through the same normalizers as runtime loading.
	// Ignored placeholders retain their original YAML and UUID, not a live slot.
	tracked := source.CloneForRuntime()
	refs, err := groupingCredentialIDRefs(tracked)
	if err != nil {
		return nil, err
	}
	positions := make(map[string]int, len(refs))
	for i, ref := range refs {
		marker := fmt.Sprintf("grouping-document-source-%d", i)
		*ref.id = marker
		positions[marker] = i
	}
	normalizeGroupingDocumentCredentials(tracked)
	active, err := groupingCredentialIDRefs(tracked)
	if err != nil || len(active) != len(newRefs) {
		return nil, fmt.Errorf("grouping: credential source sequence changed")
	}
	indices := make([]int, len(active))
	for i, ref := range active {
		index, exists := positions[*ref.id]
		if !exists || ref.path != newRefs[i].path {
			return nil, fmt.Errorf("grouping: credential source sequence changed")
		}
		indices[i] = index
	}
	return indices, nil
}

func sameGroupingDocumentCredentials(source, cfg *Config) bool {
	working := cfg.CloneForRuntime()
	normalizeGroupingDocumentCredentials(source)
	normalizeGroupingDocumentCredentials(working)
	return reflect.DeepEqual(source.GeminiKey, working.GeminiKey) &&
		reflect.DeepEqual(source.InteractionsKey, working.InteractionsKey) &&
		reflect.DeepEqual(source.ClaudeKey, working.ClaudeKey) &&
		reflect.DeepEqual(source.CodexKey, working.CodexKey) &&
		reflect.DeepEqual(source.XAIKey, working.XAIKey) &&
		reflect.DeepEqual(source.MetaKey, working.MetaKey) &&
		reflect.DeepEqual(source.VertexCompatAPIKey, working.VertexCompatAPIKey) &&
		reflect.DeepEqual(source.OpenAICompatibility, working.OpenAICompatibility)
}

func normalizeGroupingDocumentCredentials(source *Config) {
	source.Grouping.Enabled = true
	source.SanitizeGeminiKeys()
	source.SanitizeInteractionsKeys()
	source.SanitizeClaudeKeys()
	source.SanitizeCodexKeys()
	source.SanitizeXAIKeys()
	source.SanitizeMetaKeys()
	source.SanitizeVertexCompatKeys()
	source.SanitizeOpenAICompatibility()
}

func groupingDocumentCredentialNodes(root *yaml.Node) ([]*yaml.Node, error) {
	// Match groupingCredentialIDRefs rather than v8KeyFamilies' layout order.
	families := []configPath{
		{"gemini-api-key", "gemini"}, {"interactions-api-key", "interactions"},
		{"claude-api-key", "claude"}, {"codex-api-key", "codex"},
		{"xai-api-key", "xai"}, {"meta-api-key", "meta"},
		{"vertex-api-key", "vertex"}, {"openai-compatibility", "openai-compatibility"},
	}
	var nodes []*yaml.Node
	for _, family := range families {
		groups := yamlPath(root, "api-keys."+family.current)
		v8 := groups != nil
		if !v8 {
			groups = yamlPath(root, family.old)
		}
		if groups == nil || groups.Tag == "!!null" {
			continue
		}
		if groups.Kind != yaml.SequenceNode {
			return nil, fmt.Errorf("grouping: invalid source collection")
		}
		for _, group := range groups.Content {
			items, err := groupingDocumentGroupNodes(group, v8, family.current == "openai-compatibility")
			if err != nil {
				return nil, err
			}
			nodes = append(nodes, items...)
		}
	}
	return nodes, nil
}

func groupingDocumentGroupNodes(group *yaml.Node, v8, openAI bool) ([]*yaml.Node, error) {
	if group.Kind != yaml.MappingNode {
		return nil, fmt.Errorf("grouping: invalid source record")
	}
	if !v8 && !openAI {
		return []*yaml.Node{group}, nil
	}
	field := "api-key-entries"
	if v8 {
		field = "keys"
	}
	var nodes []*yaml.Node
	if openAI {
		nodes = append(nodes, group)
	}
	keys := yamlPath(group, field)
	if keys == nil || keys.Tag == "!!null" {
		return nodes, nil
	}
	if keys.Kind != yaml.SequenceNode {
		return nil, fmt.Errorf("grouping: invalid source keys")
	}
	for _, key := range keys.Content {
		if key.Kind != yaml.MappingNode {
			return nil, fmt.Errorf("grouping: invalid source key")
		}
		nodes = append(nodes, key)
	}
	return nodes, nil
}
